with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'النماذج المناخية المتقدمة ونظام الأرض','نظام الأرض والاقتران المحيطي الجوي ودورة الكربون والتغذيات الراجعة والأسس العددية ومجموعات النماذج المناخية.',45,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'فيزياء المناخ ومكونات نظام الأرض',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'النمذجة المناخية والتحليل طويل الأمد',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('earth-system-model-components','مكونات نماذج نظام الأرض','الغلاف الجوي والمحيطات واليابسة والجليد والكربون.','{"blocks":[{"type":"text","text":"يتناول الدرس مكونات نماذج نظام الأرض ضمن فهم نظام الأرض والنماذج المستخدمة لمحاكاة تطور المناخ."},{"type":"text","text":"الفكرة الأساسية: الغلاف الجوي والمحيطات واليابسة والجليد والكربون.، ويجب ربطها بميزانية الطاقة والماء والزخم والتفاعلات بين مكونات النظام."},{"type":"text","text":"تحدد المكونات والعمليات والمتغيرات التي تمثلها الدراسة والمقياس الزمني والمكاني."},{"type":"text","text":"تراجع المعادلات أو المعاملات أو البيانات المستخدمة مع توثيق الافتراضات وحدود التمثيل."},{"type":"text","text":"توضح التفاعلات بين المكونات والتغذيات الراجعة والتأخر الزمني عند تفسير الاستجابة المناخية."},{"type":"text","text":"تستخدم المحاكاة التاريخية والسيناريوهات والتجارب الحساسة لفهم مصادر الاختلاف بين النتائج."},{"type":"text","text":"تراعى دقة الشبكة والتهيئة والشروط الحدية والمعاملات الفيزيائية عند مقارنة النماذج."},{"type":"text","text":"يحلل التذبذب الطبيعي إلى جانب الإشارة القسرية، خصوصاً في الفترات القريبة أو المناطق ذات التباين العالي."},{"type":"text","text":"تقيم المخرجات مقابل الرصد أو إعادة التحليل مع اختيار مقاييس مناسبة للمتغير والمنطقة."},{"type":"text","text":"تعرض النتائج كنطاقات متعددة النماذج والسيناريوهات مع بيان مصادر عدم اليقين."},{"type":"text","text":"مثال تطبيقي: مقارنة استجابة متغير مناخي في مجموعة نماذج تحت أكثر من سيناريو مع تحليل التباين الإقليمي."},{"type":"callout","text":"الخلاصة: فهم الإسقاطات يتطلب معرفة فيزياء نظام الأرض وحدود النماذج والتذبذب الطبيعي وعدم اليقين."}]}',5360,65,'["شرح مكونات أو عمليات نظام الأرض","تفسير مخرجات النماذج ضمن حدودها","تحليل التباين وعدم اليقين"]','فيزياء المناخ ومكونات نظام الأرض'),
